ruleBookInfo.tocUrl:
@js:(function(){
var u=String(book.bookUrl);
var bm=u.match(/book\/([0-9A-Z]+)\.html/);
var id=bm?bm[1]:'';
var pages=0;
try{pages=(String(result).match(/<option[^>]*value="\d+"/g)||[]).length;}catch(e){}
if(pages<1){
  try{pages=(String(java.ajax(u,{'User-Agent':'Mozilla/5.0 (Linux; Android 13) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36'})).match(/<option[^>]*value="\d+"/g)||[]).length;}catch(e){}
}
if(pages<1)pages=1;
var body='data='+encodeURIComponent(java.aesEncodeToString(JSON.stringify({id:id,page:1}),'Hi3yccTfyPoxfoexMyZ2ohk0xFgjj1mN','AES/CBC/PKCS5Padding','2685853201487428'));
return 'https://www.mopbook.com/index.php?action=loadChapterPage&page=1&pages='+pages+'&id='+id+',{"method":"POST","body":"'+body+'"}';
})()

ruleToc.nextTocUrl:
@js:(function(){
var d;
try{d=(typeof result==='string')?JSON.parse(result):result;}catch(e){return '';}
var rows=null;
try{if(typeof d.get==='function'){rows=d.get('data');}else{rows=d.data;}}catch(e){try{rows=d.data;}catch(e2){return '';}}
if(rows==null)return '';
var n=rows.length;
if(n==null&&rows.size){try{n=rows.size();}catch(e){n=0;}}
if(!n||n<100)return '';
var m=String(baseUrl).match(/[?&]page=(\d+)/);
var p=m?parseInt(m[1]):1;
var pm=String(baseUrl).match(/[?&]pages=(\d+)/);
var pages=pm?parseInt(pm[1]):100;
if(p>=pages||p>=100)return '';
var next=p+1;
var im=String(baseUrl).match(/[?&]id=([0-9A-Z]+)/);
var id=im?im[1]:'';
if(!id){var bm=String(book.bookUrl).match(/book\/([0-9A-Z]+)\.html/);id=bm?bm[1]:'';}
var body='data='+encodeURIComponent(java.aesEncodeToString(JSON.stringify({id:id,page:next}),'Hi3yccTfyPoxfoexMyZ2ohk0xFgjj1mN','AES/CBC/PKCS5Padding','2685853201487428'));
return 'https://www.mopbook.com/index.php?action=loadChapterPage&page='+next+'&pages='+pages+'&id='+id+',{"method":"POST","body":"'+body+'"}';
})()
